ALL_INTERMEDIATE_QUIZZES = []
for _wk, _wdata in INTERMEDIATE_ACCOUNTING_WEEKS.items():
    ALL_INTERMEDIATE_QUIZZES.extend(_wdata["quizzes"])


@app.route("/api/load-preset", methods=["POST"])
def load_preset():
    """중급회계1 (1~7주차 492페이지 분량) 선택 주차별 핵심 강의요약 및 적중 예상 족보 세팅"""
    data = request.get_json() or {}
    selected_weeks = data.get("weeks", [])

    all_week_keys = ["1주차", "2주차", "3주차", "4주차", "5주차", "6주차", "7주차"]
    valid_weeks = [w.strip() for w in selected_weeks if isinstance(w, str) and w.strip() in INTERMEDIATE_ACCOUNTING_WEEKS]

    if not valid_weeks or "all" in [str(w).strip() for w in selected_weeks]:
        target_weeks = all_week_keys
        week_label = "1~7주차 전범위"
    else:
        target_weeks = [w for w in all_week_keys if w in valid_weeks]
        week_label = ", ".join(target_weeks)

    notes_blocks = []
    quiz_blocks = []
    week_notes_list = []
    instant_questions = []
    quiz_idx = 1

    for wk in target_weeks:
        wdata = INTERMEDIATE_ACCOUNTING_WEEKS[wk]
        notes_blocks.append(wdata["lecture_notes"])
        week_notes_list.append({
            "week": wk,
            "title": wdata["title"],
            "lecture_notes": wdata["lecture_notes"],
            "quiz_count": len(wdata["quizzes"])
        })
        for q in wdata["quizzes"]:
            opt_str = "\n".join([f"  {i+1}. {opt}" for i, opt in enumerate(q["options"])])
            block = (
                f"[중급회계1 적중예상 {quiz_idx}] ({wk})\n"
                f"문제: {q['question']}\n"
                f"선택지:\n{opt_str}\n"
                f"[검증된 정답 및 해설]: {q['answer']}"
            )
            quiz_blocks.append(block)

            formatted_opts = [f"{i+1}. {opt}" for i, opt in enumerate(q["options"])]
            m_ans = re.search(r"정답\s*(\d+)번", q["answer"])
            ans_idx = int(m_ans.group(1)) - 1 if m_ans else 0
            if ans_idx < 0 or ans_idx >= len(formatted_opts):
                ans_idx = 0

            instant_questions.append({
                "id": quiz_idx,
                "type": "multiple_choice",
                "question": q["question"],
                "code_snippet": "",
                "options": formatted_opts,
                "correct_answer": formatted_opts[ans_idx],
                "explanation": q["answer"],
                "keywords": [],
                "source_tag": f"{wk} 실전 기출/예상",
                "difficulty": "실전 기출"
            })
            quiz_idx += 1

    full_notes = "\n\n========================================\n\n".join(notes_blocks)
    full_quizzes = "\n\n".join(quiz_blocks)

    instant_exam = {
        "exam_title": f"중급회계1 [{week_label}] 실전 수업퀴즈(LearningX) & 연습문제 ({len(instant_questions)}문항)",
        "subject": f"중급회계1 ({week_label})",
        "total_questions": len(instant_questions),
        "time_limit_minutes": 0,
        "questions": instant_questions
    }

    logging.info(f"📚 중급회계1 프리셋 로드 완료: {week_label} (예상문제 {quiz_idx - 1}문항)")
    return jsonify({
        "success": True,
        "selected_weeks": target_weeks,
        "week_label": week_label,
        "quiz_count": quiz_idx - 1,
        "subject": f"중급회계1 ({week_label} 중간고사 대비)",
        "title": f"중급회계1 핵심요약 & 말바꾸기 함정 족보 [{week_label}]",
        "lecture_notes": full_notes,
        "practice_problems": full_quizzes,
        "week_notes_list": week_notes_list,
        "instant_exam": instant_exam
    })


def _extract_gemini_share_chat(url: str, headers: dict):
    """share.gemini.google 또는 gemini.google.com/share/<id> 공개 링크에서 전체 대화 추출"""
    resp = requests.get(url, headers=headers, timeout=10, allow_redirects=True)
    resp.raise_for_status()
    final_url = resp.url
    m = re.search(r"/share/([a-zA-Z0-9_-]+)", final_url)
    if not m:
        return None
    share_id = m.group(1)

    rpc_url = f"https://gemini.google.com/_/BardChatUi/data/batchexecute?rpcids=ujx1Bf&source-path=%2Fshare%2F{share_id}&hl=ko&rt=c"
    payload = {
        "f.req": json.dumps([[["ujx1Bf", json.dumps([None, share_id]), None, "generic"]]])
    }
    rpc_headers = {
        **headers,
        "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8",
        "Origin": "https://gemini.google.com",
        "Referer": final_url,
    }
    rpc_resp = requests.post(rpc_url, data=payload, headers=rpc_headers, timeout=12)
    rpc_resp.raise_for_status()

    turns_text = []
    for line in rpc_resp.text.splitlines():
        if '"wrb.fr","ujx1Bf"' in line:
            arr = json.loads(line)
            inner = json.loads(arr[0][2])
            # inner[0][1] contains list of conversation turns
            turns = inner[0][1] if (inner and inner[0] and len(inner[0]) > 1) else []
            for idx, turn in enumerate(turns, 1):
                user_prompt = ""
                try:
                    user_prompt = turn[2][0][0] or ""
                except Exception:
                    pass
                model_reply = ""
                try:
                    model_reply = turn[3][0][0][1][0] or ""
                    model_reply = re.sub(r"\[cite:\s*\d+\]", "", model_reply)
                except Exception:
                    pass
                if user_prompt or model_reply:
                    block = f"=== [질문 {idx}] ===\n{user_prompt if user_prompt else '(문제 이미지 첨부)'}\n\n[제미나이 풀이 및 해설]\n{model_reply}"
                    turns_text.append(block)
            break

    if not turns_text:
        return None
    return {
        "title": f"Gemini 공유 대화 ({share_id}, 총 {len(turns_text)}개 문답)",
        "url": final_url,
        "text": "\n\n".join(turns_text),
    }


@app.route("/api/extract-url", methods=["POST"])
def extract_url():
    """웹페이지 링크(URL)에서 핵심 텍스트를 스크랩하여 추출 (Gemini 공유 링크 완벽 지원)"""
    data = request.get_json() or {}
    url = data.get("url", "").strip()

    if not url:
        return jsonify({"success": False, "error": "URL 주소를 입력해 주세요."}), 400

    if not (url.startswith("http://") or url.startswith("https://")):
        url = "https://" + url

    try:
        headers = {
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
        }

        # Gemini 공유 링크(share.gemini.google / gemini.google.com/share/...) 전용 추출
        if "share.gemini.google" in url or "gemini.google.com/share" in url:
            gemini_data = _extract_gemini_share_chat(url, headers)
            if gemini_data:
                logging.info(f"✨ Gemini 공유 링크 추출 완료: {url} ({len(gemini_data['text'])}자)")
                return jsonify({
                    "success": True,
                    "title": gemini_data["title"],
                    "url": gemini_data["url"],
                    "text": gemini_data["text"],
                })

        resp = requests.get(url, headers=headers, timeout=10)
        resp.raise_for_status()

        resp.encoding = resp.apparent_encoding or "utf-8"
        soup = BeautifulSoup(resp.text, "html.parser")

        # 불필요한 태그 제거 (스크립트, 스타일, 네비게이션, 푸터 등)
        for tag in soup(["script", "style", "nav", "footer", "header", "noscript", "iframe"]):
            tag.decompose()

        title = soup.title.string.strip() if soup.title and soup.title.string else "웹페이지 본문"
        
        # 본문 텍스트 추출 및 정돈
        text = soup.get_text(separator="\n")
        lines = [line.strip() for line in text.splitlines() if line.strip()]
        clean_text = "\n".join(lines)

        if len(clean_text) > 30000:
            clean_text = clean_text[:30000] + "\n...(이하 생략)"

        if len(clean_text) < 50:
            return jsonify({
                "success": False,
                "error": "해당 웹페이지에서 충분한 텍스트 내용을 가져오지 못했습니다. 로그인이 필요한 페이지인지 확인해 주세요."
            }), 400

        logging.info(f"🔗 URL 웹페이지 추출 완료: {url} (제목: {title}, 길이: {len(clean_text)}자)")
        return jsonify({
            "success": True,
            "title": title,
            "url": url,
            "text": clean_text
        })

    except requests.exceptions.Timeout:
        return jsonify({"success": False, "error": "해당 링크의 응답 시간이 초과되었습니다 (Timeout)."}), 408
    except requests.exceptions.RequestException as e:
        return jsonify({"success": False, "error": f"웹페이지를 불러올 수 없습니다: {str(e)}"}), 400
    except Exception as e:
        return jsonify({"success": False, "error": f"웹페이지 분석 중 오류: {str(e)}"}), 500

@app.route("/api/generate", methods=["POST"])
def generate_exam():
    if not client:
        return jsonify({"success": False, "error": "Gemini API 키가 서버에 설정되지 않았습니다."}), 500

    try:
        data = request.get_json() or {}
        lecture_notes = data.get("lecture_notes", "").strip()
        practice_problems = data.get("practice_problems", "").strip()
        subject_name = data.get("subject_name", "중간고사 대비 시험").strip() or "중간고사 대비 시험"
        mode = data.get("mode", "hit_focus")  # "hit_focus" (족보 적중 모드) or "comprehensive" (개념 종합)
        question_count = int(data.get("question_count", 10))
        # 1문제부터 최대 50문제까지 지원
        question_count = max(1, min(50, question_count))

        # 시험 제한 시간 (분): 0이면 무제한, None이면 문항당 2분(최소 10분) 자동 계산
        time_limit_raw = data.get("time_limit_minutes", None)
        if time_limit_raw is not None and str(time_limit_raw).isdigit():
            time_limit_minutes = int(time_limit_raw)
        else:
            time_limit_minutes = max(10, question_count * 2)

        question_types = data.get("question_types", "mix")  # "mix", "multiple_choice", "subjective"
        difficulty = data.get("difficulty", "hard")  # "hard", "standard", "basic"

        if not lecture_notes and not practice_problems:
            return jsonify({"success": False, "error": "강의 자료 내용이나 예상 연습문제를 하나 이상 입력해 주세요."}), 400

        logging.info(f"📝 시험 생성 요청: 과목={subject_name}, 모드={mode}, 난이도={difficulty}, 문항수={question_count}, 제한시간={time_limit_minutes}분, 유형={question_types}")

        prompt = f"""
[Role & Context]
너는 한국회계기준원(KASB) 연구원 출신이자 공인회계사·세무사로서 대학 회계학/전공 시험을 출제하는 꼼꼼한 대학교수다.
입력된 PPT/문서 자료와 핵심 족보만을 바탕으로, 학술적·회계기준상 오류가 전혀 없는 정교한 실전 중간고사 문제를 생성하라.
학생이 제공한 자료를 정밀 분석하여 실제 대학교 중간고사 시험에 출제될 확률이 매우 높은 실전 모의고사 {question_count}문항을 생성해 주세요.

[Strict Presentation Rules & 중급회계(K-IFRS) 말문제 특화 지침]
1. 모든 정답 및 오답 선지는 입력된 강의 자료 및 K-IFRS(특히 최신 제정 K-IFRS 제1118호 '재무제표의 표시와 공시', 개정 제1008호 '재무제표의 작성기준', 개념체계, 제1016호 유형자산)의 명확한 'Fact'에만 기반해야 한다.
2. 오답 선지(틀린 설명)를 만들 때는 실제 회계사·세무사·대학 중간고사에서 교수님들이 가장 즐겨 쓰는 **기준서 말바꾸기 함정**을 사용하라:
   - 예1: 역선택(사전적 정보비대칭)과 도덕적 해이(사후적 정보비대칭)를 반대로 서술하거나, 주기적 지정제(6년 자유선임 + 3년 지정) 숫자를 변경
   - 예2: 개념체계의 위상(개별 기준서가 우선함), 신중성(비대칭성을 필연적으로 내포하지 않음), 오류가 없는 서술(완벽한 정확성을 의미하지 않음), 보강적 질적특성 한계, 즉시 소비되는 용역의 자산성, 자기주식·자기사채의 비자산성
   - 예3: 측정기준에서 거래원가 포함 여부(공정가치는 취득·처분 거래원가 모두 불포함 vs 역사적원가·현행원가는 취득 거래원가 포함 vs 사용가치·이행가치는 처분·이행 거래원가 반영)
   - 예4: 재분류조정 가능(FVOCI 채무상품) vs 불가능(FVOCI 선택 지분상품, 재평가잉여금), 재무적 자본유지 vs 실물적 자본유지(현행원가 적용, 가격변동분은 자본유지조정)
   - 예5: K-IFRS 제1118호 손익계산서 5대 범주(영업·투자·재무·법인세·중단영업)에서 일반 기업의 현금및현금성자산 이자수익은 '투자 범주'인데 '재무 범주'로 속이거나, 평가충당금 차감 표시를 '상계'라고 속이는 함정
   - 예6: 정상영업주기 내 실현되는 매출채권·재고자산은 12개월 초과 시에도 '유동자산', 보고기간 후 장기차환 약정 체결 시 보고기간말 현재 '유동부채', 제1118호 문단 118의 매출총손익·OPBDA는 '경영진이 정의한 성과측정치(MPM)가 아님', 유형자산 시운전 시제품 판매수익은 취득원가 차감이 아니라 '당기손익 인식'
3. 문제 생성 후, 스스로 각 선지(1번~4번)를 다시 검토하여 "해석에 따라 정답이 바뀔 여지가 있는가?"를 셀프 피드백하고, 조금이라도 모호하다면 선지를 더 명확한 문장으로 전면 수정하여 출력하라.

[입력된 과목명]
{subject_name}

[출제 모드 및 족보·교안 예제 활용 원칙]
- {"🎯 족보 적중 모드: [입력 데이터 2: 핵심 예상문제·족보]의 문제들과 [입력 데이터 1: 강의 자료 내 핵심 이론·계산 예제]를 최우선으로 반영하여 출제하세요!" if mode == "hit_focus" else "📚 개념 심화 모드: [입력 데이터 1: 강의 자료] 전 범위의 세부 말문제 포인트와 계산 예제를 골고루 조합하여 새로운 응용·심화 문제까지 폭넓게 출제하세요."}
- 【★계산 예제(자본유지개념 이익, 현재가치/상각후원가, 평균영업주기, 복구충당부채) 출제 지침★】:
  1. 강의 자료에 등장하는 계산 예제(예: 5주차 자본유지개념별 당기순이익, 장기미수금 현재가치, 7주차 평균영업주기 120일, 설비 복구충당부채 현재가치 75,131원 및 취득원가 1,075,131원)를 출제할 때는 **교안에 수록된 예제 수치와 조건, 풀이 식, 최종 정답 금액을 그대로** 사용하여 계산 오류를 원천 차단하세요!
  2. 계산 문제의 `explanation`에는 반드시 `[단계별 계산 풀이] 1단계: ... -> 2단계: ... -> 3단계: ... -> 따라서 최종 정답: ...` 형태로 누구나 한눈에 이해할 수 있게 정석 풀이 과정을 서술하세요.

[문항 유형 요구사항]
- 요청 유형: {question_types}
- {"객관식(4지선다)을 중심으로 출제하되 핵심 용어를 묻는 주관식 단답형을 일부 포함하세요." if question_types == "mix" else ("모든 문제를 4지선다 객관식으로 출제하세요." if question_types == "multiple_choice" else "모든 문제를 주관식 단답형(핵심 용어, 기준서 개념, 계산 금액 쓰기)으로 출제하세요.")}

[입력 데이터 1: 교수님 강의 자료 및 주차별 핵심 요약]
{lecture_notes if lecture_notes else "(입력 없음)"}

[입력 데이터 2: 핵심 예상문제 및 말바꾸기 함정 족보]
{practice_problems if practice_problems else "(입력 없음)"}

[주차별 균형 출제 원칙]
- 제공된 자료에 여러 주차(1주차~7주차)가 포함된 경우, 특정 주차에만 치우치지 말고 선택된 모든 주차에서 골고루 문제를 배분하여 {question_count}문항을 구성하세요.

[출제 규칙]
1. 객관식(multiple_choice):
   - options는 4개의 명확한 보기를 제공합니다 (예: ["1. ...", "2. ...", "3. ...", "4. ..."]).
   - correct_answer는 options 중 정답 보기 문자열과 정확히 일치해야 합니다.
2. 주관식(subjective):
   - options는 빈 배열 []로 둡니다.
   - 질문은 단답형으로 떨어질 수 있게 명확해야 합니다 (예: "~하는 개념의 명칭은 무엇인가?", "~에 들어갈 핵심 용어를 쓰시오").
   - correct_answer는 대표 모범 정답입니다.
   - keywords에는 채점에 필요한 핵심 키워드 리스트를 2~4개 작성하세요.
3. explanation(해설 - ★반드시 options 및 correct_answer보다 먼저 작성하여 선지 설계·계산 검산을 완료한 후 보기를 출력할 것★):
   - JSON 출력 시 반드시 `explanation` 필드를 `options`와 `correct_answer`보다 **먼저** 작성하세요!
   - "옳지 않은 것은?" 문제를 출제할 때는 `explanation`에서 먼저 몇 번 보기를 어떤 말바꾸기 함정(틀린 설명)으로 만들지 명확히 설계한 뒤, `options`에 실제로 그 **틀린 문장**을 배치하세요. (절대로 해설의 '올바르게 고친 문장'을 보기에 넣어서 모든 보기가 옳은 문장이 되는 실수를 하지 마세요!)
   - 각 오답 선지 왜 맞는지/틀리는지 조목조목 짚어주고 마지막에 `[시험장 핵심 암기 포인트]`를 한 줄로 요약해 주세요.
4. source_tag:
   - 이 문제가 몇 주차 어느 주제에서 출제되었는지 표기합니다 (예: "6주차 K-IFRS 제1118호 손익 5대 범주", "7주차 유동/비유동 분류 및 MPM").

반드시 아래 JSON 형식으로만 응답하세요 (`explanation`을 가장 먼저 작성하여 계산과 선지 정·오답 설계를 끝낸 뒤 `options`와 `correct_answer`를 출력하는 순서를 엄격히 지키세요). 백틱(`) 마크다운 코드블록이나 불필요한 설명 없이 순수 JSON 텍스트만 출력하세요:
{{
  "exam_title": "{subject_name} 실전 모의고사",
  "subject": "{subject_name}",
  "total_questions": {question_count},
  "time_limit_minutes": {time_limit_minutes},
  "questions": [
    {{
      "id": 1,
      "type": "multiple_choice",
      "question": "문제 내용...",
      "code_snippet": "필요한 경우 [사례/재무자료] 박스 텍스트, 없으면 빈 문자열",
      "explanation": "[선지 분석 및 정답 도출] 먼저 정확히 분석하고 1~4번 중 어느 선지를 틀린/옳은 보기로 구성할지 명확히 해설...",
      "options": [
        "1. 보기 내용",
        "2. 보기 내용",
        "3. 보기 내용",
        "4. 보기 내용"
      ],
      "correct_answer": "1. 보기 내용",
      "keywords": [],
      "source_tag": "6주차 K-IFRS 제1118호 손익계산서 범주",
      "difficulty": "상"
    }}
  ]
}}

[JSON 출력 필수 규칙]
1. 유효한 단 하나의 JSON 객체만을 출력하세요. 백틱이나 불필요한 설명은 금지합니다.
2. 문자열 내부(질문, 보기, 해설 등)에서 회사명이나 인용구를 쓸 때는 큰따옴표(") 대신 반드시 작은따옴표(')를 사용하세요. (예: '(주)한국'처럼 작성)
3. 배열이나 객체의 마지막 원소 뒤에 쉼표(Trailing comma)를 절대 붙이지 마세요.
4. `correct_answer`는 반드시 `explanation`에서 도출한 최종 계산 결과 및 정답 번호와 100% 일치해야 합니다.
5. "옳지 않은 것은?" 문제에서 `options`의 정답 선지는 반드시 명백히 **틀린 내용**으로 작성되어 있어야 하며, 모든 선지가 옳은 내용이 되는 일이 절대 없도록 하세요.
"""

        response = client.models.generate_content(
            model=GEMINI_MODEL,
            contents=prompt,
            config=types.GenerateContentConfig(
                temperature=0.25,
                response_mime_type="application/json",
                max_output_tokens=8192
            )
        )

        exam_data = clean_json_response(response.text)

        # 1차 후처리 검증: 내장된 중급회계1 검증 퀴즈와 동일한 질문이 출제된 경우 검증된 정답·해설 매칭
        for q in exam_data.get("questions", []):
            q_title = str(q.get("question", "")).strip()
            for iq in ALL_INTERMEDIATE_QUIZZES:
                iq_q = iq["question"].strip()
                if iq_q in q_title or q_title in iq_q:
                    ans_match = re.search(r"정답\s*([1-4])\s*번", iq["answer"])
                    if ans_match:
                        correct_num = int(ans_match.group(1))
                        formatted_opts = [f"{i+1}. {opt}" for i, opt in enumerate(iq["options"])]
                        q["options"] = formatted_opts
                        q["correct_answer"] = formatted_opts[correct_num - 1]
                        q["explanation"] = f"[검증된 중급회계1 정석 해설] {iq['answer']}"
                        q["source_tag"] = f"중급회계1 핵심족보 ({iq['session']})"
                    break

        # 2차 후처리 검증: 일반 생성 문항에서 해설(explanation) 결론 번호와 correct_answer 불일치 시 자동 교정
        for q in exam_data.get("questions", []):
            if q.get("type") == "multiple_choice" and q.get("options"):
                exp_text = str(q.get("explanation", ""))
                cur_ans = str(q.get("correct_answer", "")).strip()
                options = [str(o).strip() for o in q.get("options", [])]

                matches = re.findall(r"(?:최종\s*정답|따라서\s*정답|정답)\s*(?:은|은\s*바로|:|은\s*보기)?\s*([1-5])\s*번", exp_text)
                if matches:
                    declared_num = matches[-1]
                    if not cur_ans.startswith(f"{declared_num}."):
                        for opt in options:
                            if opt.startswith(f"{declared_num}."):
                                logging.info(f"🔧 [자동 교정] 문항 Q{q.get('id')}: 해설 결론({declared_num}번)에 맞춰 correct_answer를 '{cur_ans}' -> '{opt}'로 자동 수정했습니다.")
                                q["correct_answer"] = opt
                                break

        exam_data["time_limit_minutes"] = time_limit_minutes
        exam_data["total_questions"] = len(exam_data.get("questions", []))
        logging.info(f"✅ 시험 출제 완료: 총 {len(exam_data.get('questions', []))}문제, 제한시간={time_limit_minutes}분")
        return jsonify({"success": True, "exam": exam_data})

    except Exception as e:
        logging.error(f"❌ 시험 생성 중 오류: {e}")
        return jsonify({"success": False, "error": f"시험 생성 중 오류가 발생했습니다: {str(e)}"}), 500

@app.route("/api/grade", methods=["POST"])
def grade_exam():
    """사용자가 제출한 답안을 채점하고 결과 점수와 AI 처방 분석을 제공"""
    try:
        data = request.get_json() or {}
        questions = data.get("questions", [])
        user_answers = data.get("user_answers", {})
        time_spent_seconds = data.get("time_spent_seconds", 0)

        if not questions:
            return jsonify({"success": False, "error": "채점할 문항 정보가 없습니다."}), 400

        graded_questions = []
        correct_count = 0
        total_questions = len(questions)

        for q in questions:
            qid = str(q.get("id"))
            q_type = q.get("type", "multiple_choice")
            correct_ans = str(q.get("correct_answer", "")).strip()
            user_ans = str(user_answers.get(qid, "")).strip()
            keywords = q.get("keywords", [])

            is_correct = False
            earned_points = 0
            point_per_q = round(100.0 / total_questions, 1)

            if q_type == "multiple_choice":
                # 객관식: 완전 일치 또는 앞 번호 매칭
                if user_ans and (user_ans == correct_ans or user_ans[:2] == correct_ans[:2]):
                    is_correct = True
                    earned_points = point_per_q
                    correct_count += 1
            else:
                # 주관식: 키워드 포함 검사 또는 문자열 정규화 비교
                norm_user = user_ans.lower().replace(" ", "")
                norm_correct = correct_ans.lower().replace(" ", "")
                if norm_user and (norm_user == norm_correct or any(kw.lower().replace(" ", "") in norm_user for kw in keywords if kw)):
                    is_correct = True
                    earned_points = point_per_q
                    correct_count += 1
                elif not user_ans:
                    is_correct = False
                    earned_points = 0

            graded_questions.append({
                "id": q.get("id"),
                "type": q_type,
                "question": q.get("question"),
                "code_snippet": q.get("code_snippet", ""),
                "options": q.get("options", []),
                "user_answer": user_ans if user_ans else "(미응답)",
                "correct_answer": correct_ans,
                "is_correct": is_correct,
                "explanation": q.get("explanation", ""),
                "source_tag": q.get("source_tag", ""),
                "difficulty": q.get("difficulty", "보통"),
                "earned_points": earned_points
            })

        score = round((correct_count / total_questions) * 100)
        
        # 등급 산정
        if score >= 95: grade = "A+"
        elif score >= 90: grade = "A0"
        elif score >= 85: grade = "B+"
        elif score >= 80: grade = "B0"
        elif score >= 75: grade = "C+"
        elif score >= 70: grade = "C0"
        elif score >= 60: grade = "D"
        else: grade = "F"

        # 즉시 종합 학습 진단 생성 (외부 AI API 재호출 대기 없이 0.01초 만에 오답 출처 기반 정밀 처방 생성)
        wrong_items = [g for g in graded_questions if not g["is_correct"]]
        if not wrong_items:
            ai_prescription = (
                f"🎉 완벽합니다! 총 {total_questions}문항을 모두 맞혀 100점({grade})을 달성하셨습니다. "
                f"개념 이해와 다단계 계산 응용력이 모두 실전 중간고사 만점 수준입니다. "
                f"전체 문항의 핵심 해설과 시험 꿀팁만 가볍게 1회독 점검하시고 자신감 있게 시험장에 입장하세요!"
            )
        else:
            weak_tags = []
            for w in wrong_items:
                tag = (w.get("source_tag") or "").strip()
                if tag and tag not in weak_tags:
                    weak_tags.append(tag)
            tag_summary = ", ".join(weak_tags[:4]) if weak_tags else "핵심 개념 및 계산 응용"
            ai_prescription = (
                f"총 {total_questions}문항 중 {correct_count}문항 정답({score}점, {grade} 등급)을 기록하셨습니다! "
                f"집중 보완이 필요한 취약 영역은 [{tag_summary}] 파트(오답 {len(wrong_items)}문항)입니다. "
                f"하단 '오답 노트' 탭을 눌러 틀린 문제의 [선지별 정·오답 분석]과 [단계별 계산 풀이]를 다시 풀어보시면 실제 시험에서 최소 15~20점 이상 즉시 상승할 수 있습니다!"
            )

        return jsonify({
            "success": True,
            "score": score,
            "grade": grade,
            "correct_count": correct_count,
            "wrong_count": total_questions - correct_count,
            "total_questions": total_questions,
            "time_spent_seconds": time_spent_seconds,
            "graded_questions": graded_questions,
            "ai_prescription": ai_prescription
        })

    except Exception as e:
        logging.error(f"❌ 채점 중 오류: {e}")
        return jsonify({"success": False, "error": f"채점 중 오류가 발생했습니다: {str(e)}"}), 500

